194	+pub fn checkpoint_input_changes<R: CommandRunner, D: DependencyResolver>(
195	+    ws: &Workspace<'_, R, D>,
196	+    checkpoint: &callisto_model::vcs::Checkpoint,
197	+    now: &callisto_model::vcs::CheckpointFacts,
198	+) -> Result<Vec<String>, GraphError> {
199	+    let then = &checkpoint.facts;
200	+    let mut changes = Vec::new();
201	+    if now.head != then.head {
202	+        changes.push(format!("`HEAD` moved from {} to {}", then.head, now.head));
203	+    }
204	+    if now.tags != then.tags {
205	+        changes.push("tags changed".to_string());
206	+    }
207	+    if now.callisto_version != then.callisto_version {
208	+        changes.push(format!(
209	+            "Callisto changed from {} to {}",
210	+            then.callisto_version, now.callisto_version
211	+        ));
212	+    }
213	+    let git = ws.git_access();
214	+    let rev = checkpoint.commit.as_str();
215	+    let dir = &ws.config.changesets_dir;
216	+    let mut paths: BTreeSet<std::path::PathBuf> = git.files_at(rev, dir)?.into_iter().collect();
217	+    if let Ok(entries) = std::fs::read_dir(ws.root.join(dir)) {
218	+        paths.extend(
219	+            entries
220	+                .flatten()
221	+                .filter(|entry| entry.path().is_file())
222	+                .map(|entry| dir.join(entry.file_name())),
223	+        );
224	+    }
225	+    paths.remove(&ws.config.pre_json_path());
226	+    let config = std::path::PathBuf::from("callisto.toml");
227	+    paths.insert(config.clone());
228	+    for path in paths {
229	+        let recorded = git.read_at(rev, &path)?;
230	+        let current = std::fs::read_to_string(ws.root.join(&path)).ok();
231	+        // A changeset that is gone was consumed by the interrupted run itself.
232	+        let consumed = path != config && recorded.is_some() && current.is_none();
233	+        if recorded != current && !consumed {
234	+            changes.push(format!("`{}` changed", path.display()));
235	+        }
236	+    }
237	+    Ok(changes)
