454	+/// Where an interrupted `callisto version` run keeps its inputs.
455	+pub const VERSION_CHECKPOINT: &str = "refs/callisto/checkpoint/version";
456	+
457	+const HEAD_TRAILER: &str = "Callisto-Head";
458	+const TAGS_TRAILER: &str = "Callisto-Tags";
459	+const VERSION_TRAILER: &str = "Callisto-Version";
