461	+/// The inputs a plan reads besides files, recorded in the checkpoint commit's message.
462	+#[derive(Clone, Debug, PartialEq, Eq)]
463	+pub struct CheckpointFacts {
464	+    pub head: String,
465	+    pub tags: String,
466	+    pub callisto_version: String,
