469	+/// A recorded checkpoint: a commit whose tree is the working tree, whose first parent is `HEAD` and whose second
470	+/// parent records the index.
471	+#[derive(Clone, Debug)]
472	+pub struct Checkpoint {
473	+    pub commit: CommitSha,
474	+    pub facts: CheckpointFacts,
475	+}
