477	+impl GitAccess<'_> {
478	+    /// The checkpoint at `name`, or `None` when there is none.
479	+    pub fn checkpoint(&self, name: &str) -> Result<Option<Checkpoint>, VcsError> {
480	+        let Some(commit) = self.resolve_commit(name)? else {
481	+            return Ok(None);
482	+        };
483	+        let message = self.git_stdout(&["show", "-s", "--no-show-signature", "--format=%B", commit.as_str()])?;
484	+        let trailer = |key: &str| {
485	+            message
486	+                .lines()
487	+                .find_map(|line| line.strip_prefix(key)?.strip_prefix(": "))
488	+                .unwrap_or_default()
489	+                .to_string()
490	+        };
491	+        Ok(Some(Checkpoint {
492	+            facts: CheckpointFacts {
493	+                head: trailer(HEAD_TRAILER),
494	+                tags: trailer(TAGS_TRAILER),
495	+                callisto_version: trailer(VERSION_TRAILER),
496	+            },
497	+            commit,
498	+        }))
499	+    }
500	+
501	+    /// The facts a checkpoint taken now would record.
502	+    pub fn checkpoint_facts(&self, callisto_version: &str) -> Result<CheckpointFacts, VcsError> {
503	+        let tags = self.git_stdout(&["for-each-ref", "--format=%(objectname) %(refname)", "refs/tags"])?;
504	+        Ok(CheckpointFacts {
505	+            head: self.head_sha()?.as_str().to_string(),
506	+            tags: crate::release::digest::lower_hex(Sha256::digest(tags.as_bytes())),
507	+            callisto_version: callisto_version.to_string(),
508	+        })
509	+    }
510	+
511	+    /// Records `HEAD`, the index, and the working tree under this root (untracked files included, ignored files
