513	+    ///
514	+    /// # Errors
515	+    ///
516	+    /// [`VcsError::CheckpointHeld`] when `name` already exists, so two runs never share one; a failed git command
517	+    /// otherwise.
518	+    pub fn create_checkpoint(&self, name: &str, facts: &CheckpointFacts) -> Result<CommitSha, VcsError> {
519	+        let git_dir = self.git_stdout(&["rev-parse", "--absolute-git-dir"])?;
520	+        let index = Path::new(git_dir.trim()).join("callisto-checkpoint.index");
521	+        let index_str = index.to_string_lossy().into_owned();
522	+        let env = [("GIT_INDEX_FILE", index_str.as_str())];
523	+        let created = (|| {
