525	+            self.git_stdout_env(&["read-tree", "HEAD"], &env)?;
526	+            self.git_stdout_env(&["add", "-A", "--", "."], &env)?;
527	+            let tree = self.git_stdout_env(&["write-tree"], &env)?;
528	+            let message = format!(
