553	+    /// Checks the checkpoint at `name` out, detached, at `dir` (which must not exist), after pruning worktrees whose
554	+    /// directories are gone.
555	+    pub fn add_checkpoint_worktree(&self, name: &str, dir: &Path) -> Result<(), VcsError> {
