568	+    /// Untracked, not ignored files under this root, relative to it.
569	+    pub fn untracked_files(&self) -> Result<Vec<std::path::PathBuf>, VcsError> {
570	+        let listed = self.git_stdout(&["ls-files", "--others", "--exclude-standard", "--", "."])?;
571	+        Ok(listed.lines().map(std::path::PathBuf::from).collect())
572	+    }
573	+
574	+    /// The files under `dir` (relative to this root) in `rev`'s tree, relative to this root.
575	+    pub fn files_at(&self, rev: &str, dir: &Path) -> Result<Vec<std::path::PathBuf>, VcsError> {
576	+        let dir = dir.to_string_lossy();
577	+        let listed = self.git_stdout(&["ls-tree", "-r", "--name-only", rev, "--", &dir])?;
578	+        Ok(listed.lines().map(std::path::PathBuf::from).collect())
579	+    }
580	+
581	+    /// Removes a worktree [`Self::add_checkpoint_worktree`] added.
582	+    pub fn remove_worktree(&self, dir: &Path) -> Result<(), VcsError> {
583	+        let dir = dir.to_string_lossy();
584	+        self.git_stdout(&["worktree", "remove", "--force", &dir]).map(drop)
585	+    }
586	+
587	+    /// An unsigned commit of `tree` with fixed identity: it records state and is never pushed, so the user's signing
588	+    /// key and identity play no part.
589	+    fn internal_commit(&self, tree: &str, parents: &[&str], message: &str) -> Result<CommitSha, VcsError> {
590	+        let mut args = vec![
591	+            "-c",
592	+            "user.name=Callisto",
593	+            "-c",
594	+            "user.email=callisto@localhost",
595	+            "commit-tree",
596	+            "--no-gpg-sign",
597	+            tree,
598	+        ];
599	+        for parent in parents {
600	+            args.extend(["-p", parent]);
601	+        }
602	+        args.extend(["-m", message]);
603	+        let sha = self.git_stdout(&args)?;
604	+        CommitSha::parse(&sha).map_err(|e| VcsError::InvalidCommitSha {
605	+            context: "in `git commit-tree` output".to_string(),
606	+            message: e.to_string(),
607	+        })
608	+    }
609	+
610	+    fn git_stdout(&self, args: &[&str]) -> Result<String, VcsError> {
611	+        self.git_stdout_env(args, &[])
612	+    }
613	+
614	+    fn git_stdout_env(&self, args: &[&str], env: &[(&str, &str)]) -> Result<String, VcsError> {
615	+        let output = self.runner().run_with_env("git", args, self.root(), env)?;
616	+        if !output.success() {
617	+            return Err(git_failed(args, self.root(), &output.stderr));
618	+        }
619	+        Ok(output.stdout_trimmed().to_string())
620	+    }
621	+}
622	+
623	+fn git_failed(args: &[&str], root: &Path, stderr: &str) -> VcsError {
624	+    VcsError::Git(format!(
625	+        "`git {}` failed in `{}`: {}",
626	+        args.join(" "),
627	+        root.display(),
628	+        stderr.trim()
629	+    ))
630	+}
